"stn2d9": "Hasta dónde llegan los sticks y con qué brusquedad. Son tuyos, no del ajuste. Una emisora en Acro vuela esta curva; las carreras con teclado empiezan en Angle. Cambiarlos en plena ronda deja el quad donde está y el reloj en marcha.",
"1m2xvti": "Modo de vuelo",
"xjyq13": "Acro: los sticks son velocidades de giro, al soltar mantiene la actitud. Angle: los sticks son inclinación hasta el límite de 60 grados de Betaflight, al soltar se nivela. Esta carrera se vuela con el teclado, que guarda su propia elección (Carreras con teclado, en Quad); esta fila cambia esa. M en vuelo también lo cambia.",
"1r5ubv6": "Acro: los sticks son velocidades de giro, al soltar mantiene la actitud. Angle: los sticks son inclinación hasta el límite de 60 grados de Betaflight, al soltar se nivela, y la guiñada sigue siendo velocidad de giro. Los flips y rolls necesitan Acro. M en vuelo también lo cambia, y lo guarda.",
"x7vih9": "Cuántos por equipo, lo bien que juegan los bots y cuándo acaba.",
"17g8v9b": "Sigue volando aquí solo, sin bots y sin reloj.",
"11br69w": "Bots, y lo bien que graban.",
"m20i5w": "Sigue grabando aquí solo, sin bots.",
"c8vuhg": "La sala de espera: los bots, lo bueno que es cada uno, la ronda y la ventaja inicial.",
"5typne": "Vuela el colegio por tu cuenta, sin bots.",
"1afdza": "Bots, lo bien que pastorean y cuándo acaba la ronda.",
"1t8ovw1": "Sigue pastoreando aquí solo, sin bots y sin reloj.",
"1087r08": "Bots, lo buenos que son, lo largas que son las cintas y la ronda.",
"1206cs3": "Sigue volando aquí sin cintas y sin bots.",
"899bgs": "Bots, lo buenos que son, la ronda y lo fuerte que pegan los impactos.",
"172ev2t": "Sigue volando aquí sin armas y sin bots.",
"1w5pf1h": "Botones de cañón y misil",
"14d24dx": "Elige un botón o interruptor para cada uno y pruébalos.",
"d2okc9": "Volver a Minijuegos",
"j88ayy": "Continuar",
"jsscfj": "¿Se siente raro?",
"1emvcwj": "Hasta dónde llegan los sticks y el límite del acelerador. Cambiarlos aquí deja el quad donde está y el reloj en marcha.",
"17lkkrv": "Otros",
"1sc5qgc": "Tu nombre, tu emisora, gráficos y sonido.",
"6gxuho": "Termina {0}.",
"wyh1np": "Lo pesado que se siente el quad. A la derecha pesa más: cae cuando cortas el acelerador y deja de quedarse colgado en lo alto de un salto. A la izquierda pesa menos y flota. {0} es el quad tal como viene; cambiarlo en plena vuelta anula la vuelta, y una vuelta volada fuera de {1} sube al tablero público con su peso junto a tu nombre.",
"1ayl725": "Agarre al aire",
"6bttpz": "Cuánto frena el aire al quad, es decir, cuánto se desliza con los sticks centrados. A la izquierda sigue deslizando y corre más; a la derecha el aire lo agarra, se detiene antes y su velocidad máxima baja. {0} es el quad tal como viene, fijado a partir de los ajustes que enviaron los pilotos. Cambiarlo en plena vuelta anula la vuelta, y una vuelta volada fuera de {1} se publica en el tablero público con la etiqueta Tuned.",
"ior56v": "Potencia de motor",
"1x4irmq": "Cuánta velocidad dan los motores por voltio, su KV. A la izquierda es más suave: un punch más tranquilo y menos velocidad máxima. A la derecha es más potente, la batería cae más por ello y el quad hace estacionario más abajo en el stick. {0} es el quad tal como viene, fijado a partir de los ajustes que enviaron los pilotos. Cambiarlo en plena vuelta anula la vuelta, y una vuelta volada fuera de {1} se publica en el tablero público con la etiqueta Tuned.",
"1bsvonq": "Desactivado de serie. Activado, {0} se unen a Peso entre los sticks mientras el quad está en el suelo, y un vuelo con tus propios controles termina con una pregunta: ¿se sintió mejor que el quad de serie? No se envía nada a menos que digas que sí. Desactivado, el quad vuela tal como viene digan lo que digan los controles. Cambiarlo en plena vuelta anula la vuelta si cambia el quad que estás volando.",
"5xvgod": "Preguntar tras un vuelo ajustado",
"1siorg1": "Cuando termina un vuelo con tus propios controles, pregunta si se sintió mejor que el de serie. Siempre puedes responder que no, y no se envía nada sin un sí. Desactivado, nunca pregunta; los controles siguen funcionando.",
"187fv0s": "Cuéntale al trabajo de ajuste cómo vuela el quad. Una palabra basta; tu ajuste, tu ajuste de PID y tus rates van con ella.",
"16us7mj": "Idioma",
"2nnvct": "El idioma de los menús. El juego se reinicia para aplicarlo.",
"1hmyggy": "{0} se probó en este equipo y no mantuvo la imagen a tiempo, así que Auto se queda en {1} o por debajo.",
"s4dnb5": "Auto: dibujando en {0}{1}. Observa cómo llegan realmente los fotogramas, baja la resolución cuando la imagen va tarde y cambia el preajuste entre rondas.{2} Elige un preajuste para fijarlo a mano.",
"1ejndm0": "Gráficos",
"dcm8ea": "Dibuja cada fotograma directamente en la pantalla en vez de ponerlo en cola detrás de la página, lo que puede quitar uno o dos fotogramas al tiempo entre tus sticks y la imagen. Puede producir tearing.",
"1ttxrpl": "Desactivado desde la próxima carga. {0} Este navegador lo usa hasta que recargues.",
"1j0ql37": "Desactivado. {0} Recarga después de activarlo.",
"o73nnv": "La edición de Steam puede funcionar con vsync desactivado.",
"101as9w": "la pantalla se refresca a {0} Hz",
"cfutp1": "la GPU tarda unos {0} ms de más por fotograma",
"gtjdfs": "La vista de baja latencia está en uso",
"1ampkwb": "Si este monitor puede ir a más de 60 Hz, comprueba que el sistema está en su frecuencia de refresco máxima (Windows: Configuración, Pantalla, Pantalla avanzada), porque la página solo puede dibujar tan a menudo como la pantalla que recibe.",
"13d5h9g": "De la entrada a la pantalla",
"9anx43": "No se puede medir aquí",
"57y603": "Pulsa unas teclas",
"ks1elk": "Unos {0} ms",
"12jryem": "Detectando",
"h5se6q": "Leído del contexto WebGL que dibuja el mundo.",
"jgkrww": "Conecta una emisora en modo joystick. Si hay más de una conectada, aquí eliges cuál vuela.",
"1y6zyev": "Hay un dispositivo conectado, {0}. Abre esto para confirmarlo o para cambiar al teclado.",
"1a5n4iv": "Hay {0} dispositivos conectados. Mueve el que quieras. Windows los lista en el orden de Dispositivos de juego; esta pantalla es donde eliges.",
"hkrgl0": "Un circuito con puertas en un campo al aire libre, contra el reloj. Un quad de carreras grande y rápido, y cada vuelta que termines puede ir al tablero público.",
"1rnl54t": "El mismo reloj, en interior. Un whoop diminuto con ductos por un circuito que cabe en un salón.",
"1kaa7l9": "Todos los mapas de freestyle: el pueblo, las casas de Nick Burns, Heads y Joshua Bardwell, Thomas More's Shop, Sunnyfield, Shiokaze Point, Hibari Yard, y todos los mapas que los pilotos han construido y publicado en el tablero. Sin reloj, sin puertas, y los nombres de trucos son un interruptor dentro.",
"tn5ckg": "Editor",
"19ybx9k": "Haz el tuyo. Un circuito de carreras para el cinco pulgadas, una sala para el whoop o un mapa de freestyle con edificios abandonados, grúas y huecos con nombre, dibujado desde arriba y volado desde la misma página.",
"1rjxeiy": "De tu primer estacionario a una licencia pro. Aprende a volar, gana tu Licencia Novato y luego sube por un árbol de habilidades en carreras o freestyle. Empieza aquí si nunca has volado.",
"qci08u": "Árbol de habilidades",
