"3lorq6": "Volar otra vez",
"1wio94n": "Controles",
"152rjl0": "Un quad no tiene frenos ni alas. Apúntalo hacia donde quieres ir y empuja. En dos minutos habrás pasado por una puerta.",
"1l9ceev": "Simular FPV, para frikis",
"k33cv2": "Abrir la wiki de FPV",
