"2qk4m1": "Sin frenos y sin alas: para frenar o girar, apunta el quad hacia otro lado y empuja.",
"6del8m": "Emisora o mando",
"ap67uq": "Por qué funciona: la wiki de FPV",
"1uvpjn8": "Lista de trucos",
"10sqi3d": "Cada truco que el puntuador sabe nombrar, lo que paga y cómo se ve. Elige uno y míralo: el dibujo sale de la misma definición con la que compara el puntuador, así que lo que ves es exactamente lo que espera. Cada uno se ha volado y puntuado en pruebas, y eso le da un sitio aquí. Los puntos son antes del combo, que los multiplica.",
