"9kgcci": "Volar",
"1jh7nt4": "Ajustar este quad",
"wv167q": "Volar siempre el {0} aquí",
"10nopfd": "Campo de visión",
"unl4q1": "Más ancho ve más, más estrecho amplía. Estrecho imita lo que hace una lente FPV en el centro de la imagen; Estándar devuelve algo de eso a cambio de anchura; El más ancho es lo más ancho que esta imagen puede ir sin engañar, y las puertas se verán más pequeñas.",
"4emmbg": "Ojo de pez",
"1u80da4": "Curva la imagen como lo hace una lente FPV real: las esquinas se quedan donde las pone el campo de visión, los bordes se aprietan y el centro se agranda. Desactivado es una imagen recta, rectilínea. Si las vistas anchas te marean, prueba Leve o Medio, y usa un campo de visión más ancho para recuperar la anchura.",
"1ir4yll": "Ángulo de cámara",
"6gsnw2": "Cuánto se inclina la cámara hacia arriba respecto al chasis. {0} es plano, mirando a lo largo del morro. {1} es un crucero típico. De 45 a {2} es carrera. Por encima de unos 30, la guiñada empieza a inclinar el horizonte: a {3} grados, el {4} por ciento de una guiñada aparece como alabeo en la imagen. Eso es lo que hace una cámara inclinada real. Baja la velocidad máxima de guiñada en la pantalla de Rates para domarlo.",
"1vp9w8f": "La guiñada inclinará el horizonte",
"1hjxoj1": "A {0} grados de inclinación, el {1} por ciento de una guiñada aparece como alabeo en la imagen: {2} deg/s con tu velocidad de guiñada de {3} deg/s. Eso es lo que hace una cámara inclinada real, y la respuesta habitual es una guiñada más lenta. Bajar la velocidad máxima de guiñada a {4} lo deja en {5} deg/s. Puedes cambiarlo cuando quieras en la pantalla de Rates.",
"1f9wwkb": "¿Conservar este informe?",
"v5eaek": "Has escrito algo que no se ha enviado. Aquí no se guarda ningún borrador, así que cerrar ahora lo pierde.",
"13qi8go": "Enviarlo",
"ekjjsw": "Parte de: los ajustes de Betaflight del propio autor ({0} valor cambiado{1})",
"hqa4hr": "PID: como viene el ajuste",
"i1tfp3": "Peso {0}%, Agarre al aire {1}%, Potencia de motor {2}%",
"7x3x2g": "Batería {0} V por celda, lente {1} grados, inclinación {2}°",
"nnhdr0": "Es para el {0}, así que pasas a esa aeronave y a su propia clase de circuitos.",
"1axqv1t": "Mueve Agarre al aire o Potencia de motor, así que se activa el Ajuste de la sensación de vuelo, y una vuelta volada con él se publica en el tablero público con la etiqueta Tuned.",
"t9yl6f": "Sus ajustes de Betaflight ocupan el lugar de Tus cambios en esa aeronave hasta que vuelvas a poner los tuyos.",
"f50exw": "Tus gráficos, sticks, emisora y tiempos de vuelta no se tocan.",
"1e5r0vj": "Esta versión no puede volar ese ajuste. Puede que sea para una aeronave añadida más tarde.",
"1os1q6k": "Ese ajuste parte de un ajuste de Betaflight que esta versión no tiene.",
"13lnrfy": "Este navegador no pudo guardar el ajuste. El almacenamiento puede estar lleno o bloqueado.",
"ut38q5": "No se pudo abrir. Comprueba la conexión y recarga la página.",
