"1y9s6in": "{0}. Haz clic para silenciar.",
"19e4rfe": "Informar de un fallo",
"5bwmrs": "Con el título y lo que pasó basta. El mapa, los gráficos, la GPU y el navegador van con el ticket para que no tengas que escribirlos.",
"disqw2": "¿Solo vienes a contar cómo vuela? Mejor da tu opinión sobre la sensación de vuelo.",
