"1fcyypm": "Tiembla en el propwash",
"1roaxfm": "Se desvía de la actitud",
"xa7fm": "La guiñada es perezosa",
"88rizr": "El acelerador es muy sensible",
"1yg81h4": "Flotante, se desliza demasiado",
"82stot": "Clavado, sin quejas",
"2qyb3f": "¿Cómo vuela?",
"1x4knm": "Una palabra sincera guía el trabajo de ajuste más que cualquier telemetría. Solo hace falta la primera fila; tu ajuste, tu ajuste de PID y tus rates viajan con la respuesta para que también lleguen los números detrás de la sensación. Estabas volando {0}.",
"1yc8yfn": "El control de Peso entre los sticks en la pantalla de vuelo es justo para esta queja: escala el peso que carga el quad, así que cae cuando cortas el acelerador en vez de quedarse colgado. El tuyo está al {0} por ciento. Más a la derecha cae más rápido al cortar el acelerador y flota menos tras un punch corto. El estacionario sube en el stick con él, del {1} por ciento de serie al {2} en {3}. Vale la pena arrastrarlo antes de esperarnos, y una vuelta volada así sube al tablero público con su peso junto a tu nombre.",
"r74boy": "Este quad hace estacionario al {0} por ciento del stick sin límite de acelerador, así que casi todo el recorrido queda por encima del estacionario. Rates, Límite de acelerador, 75 por ciento lleva el estacionario al {1} por ciento y devuelve el control fino sin perder nada de subida que puedas usar en interior. Vale la pena probarlo antes de esperarnos.",
"1xpffsm": "Activar el ajuste de la sensación de vuelo",
"194uxup": "El ajuste de la sensación de vuelo está activado. Mientras estás en el suelo, {0} {1} junto a Peso entre los sticks. Si un ajuste se siente mejor que el de serie, al final del vuelo se te pregunta si quieres enviarlo.",
"1elhpti": "¿Quieres cambiarlo tú? El ajuste de la sensación de vuelo pone {0} junto a Peso mientras estás en el suelo: {1}. Si un ajuste se siente mejor que el de serie, puedes enviarnos los números tras el vuelo. Desactivado a menos que lo actives, y no se envía nada sin tu sí.",
"15h6xkr": "Con tus propias palabras (opcional)",
"1m200ro": "Lo que le dirías a la persona que tiene el destornillador.",
"1d67zxc": "El quad se sintió",
"ghfh85": "Algo concreto (elige los que quieras)",
"z5wkkb": "Elige una palabra de la primera fila. Con una basta.",
"1gl4sk7": "El quad se sintió {0} en esta ronda.",
"7ajpz1": "Notado: {0}.",
"1e17m8": "Gracias",
"120kk3i": "Recibido, con tu ajuste y tus rates adjuntos. Esto es justo lo que mueve el modelo de vuelo.",
"frbrff": "Ajuste enviado",
"yigmhv": "Ese ajuste está en el tablero. Gracias.",
"1xaroqk": "{0}, {1} en el aire. Si se sintió mejor que el de serie, envía los números con una palabra o dos a quienes ajustan el simulador. No se envía nada a menos que pulses Enviar.",
"12j7air": "¿Se sintió mejor que el de serie?",
"1qjshkq": "{0}. {1} en el aire con el {2}.",
"1k9f9e0": "Si fue así, puedes enviar estos números con una palabra o dos a quienes ajustan el simulador. No se envía nada a menos que pulses Enviar en la siguiente pantalla.",
"lmpjg0": "Mejor que el de serie",
"kertdk": "Igual o peor",
"bhqymg": "No preguntar más",
"159zlyr": "Gracias, es útil saberlo",
"1v1dzby": "Un ajuste que se sintió igual o peor les dice a quienes ajustan el simulador por dónde no ir. ¿Quieres enviar también este resultado? No se envía nada a menos que tú lo digas.",
"1vcax0y": "Enviar este resultado",
"13gi980": "Enviar tu ajuste",
"pve1j9": "{0}. {1} en el aire con el {2}. Esto va al tablero con tus palabras, agrupado por aeronave y por versión de la física, para que quienes ajustan el simulador vean qué prefieren los pilotos. Tu ajuste, tus rates y los mismos detalles que lleva un informe de sensación de vuelo van con ello.",
"wanvfr": "Qué cambió, y lo que le dirías a la persona que tiene el destornillador.",
"19h4t7l": "No enviar",
"2ri0l8": "Comparado con el de serie se sintió",
"ft8rhj": "El quad se sintió (opcional)",
"vzfgv1": "Elige cómo se sintió comparado con el de serie. Con uno basta.",
"132k2mx": "Tu ajuste llegó{0}, con los números, tus palabras y la versión de la física. Quienes ajustan el simulador los leen lado a lado.",
"gcrazo": "El tablero aún no se ha actualizado para aceptar ajustes, así que no se envió nada. Inténtalo más tarde.",
"hjvpvs": "Elige un circuito de cinco pulgadas, abre una sala y envía el código a tus amigos.",
