"1gh8gk1": "Tú eres la cámara. Graba las batallas de drift durante un minuto.",
"exsh29": "Vuela bajo para llevar las cabras al garaje de Heads. El reloj empieza con la primera cabra que muevas.",
"fk6a7t": "Sin reloj y sin puertas. Vuela toda la escuela.",
