"cyw1pe": "Un simulador de carreras FPV en el navegador. La controladora es Betaflight. El lenguaje de circuitos viene de Track Draw. El resto es un piloto y la gente que lo voló hasta que se sintió bien.",
"1sncokl": "Hecho por",
"kai17": "Construyó este simulador, el editor y el tablero público. Dirigió una horda de Grok y Claude por el camino.",
"1rju5ni": "Socios",
"10ax242": "Apoyan a WebFPV.",
"1fpu7yw": "Pilotos de pruebas beta",
"2sef6d": "Lo volaron hasta que se sintió como un quad.",
"lq4qk4": "La controladora",
"152d3mr": "Los rates, el bucle PID, los filtros, feedforward, TPA, iterm relax, airmode, anti-gravity. Compilados en esta página, no reescritos.",
"kfh8vm": "es GPLv3, así que esto también. La pantalla de la controladora de vuelo es un homenaje a",
"1ol0nlq": "10.10: nombres de pestañas, campos de la 4.5.1, y el clásico gris oscuro y naranja. No es esa aplicación. Sin Vue, sin MSP, sin iframe. Con agradecimiento a los desarrolladores de Betaflight.",
"kwollz": "El lenguaje de circuitos",
"91xq6y": "El editor está inspirado en",
"1v1kv66": ", de los dioses neerlandeses de los drones de",
"1ffizjn": "Las salas de RaceGOW5",
"ov7ihs": "Ocho circuitos, seis constructores, leídos de las animaciones oficiales.",
"f0ewtp": "Serie y animaciones de",
"432t9y": "La horda",
"gw6sa5": "Escrito con Grok. Construido con Claude.",
"1m26mn1": "Grok, de xAI. Muchas de las líneas, muchas de las discusiones y mucha de la terquedad sobre la sensación de vuelo.",
"1i8y2kj": "Claude, de Anthropic. La otra mitad de la horda. El mismo humano a los mandos.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad y sus marcas pertenecen a sus dueños. Las imágenes de los canales pertenecen a los pilotos. Usarlas aquí es un reconocimiento, no una afirmación de que respalden esta página. Las marcas de los socios pertenecen a los socios, mostradas con su acuerdo. WebFPV es software libre bajo",
