"1l302t4": "Prepara:",
"1ra2hmr": "Dale a un quad para quitarle salud. Cuando se vacía revienta, con confeti. Cada reventón es un punto. Un misil sigue a un quad en cuanto la caja se pone roja.",
"abeo2g": "¡A pelear!",
"43eacj": "Cada quad arrastra una cinta. Vuela a través de la de otro para cortarla. Mantén la tuya lejos de ellos. Cortada hasta el final, la cinta desaparece y su piloto también. Gana el último con cinta.",
"1tj1cwp": "¡A volar!",
"11xt3fz": "Vuela bajo detrás de una cabra y huirá de ti. Empújala al garaje de Heads. Cada cabra es de quien la metió el último, así que róbalas en la puerta.",
"1xzga63": "¡A pastorear!",
"ckuwmm": "Elige tu bando y los bots ocupan todos los demás puestos. Empieza en segundos, sin esperar a nadie.",
