"65gil7": "Vuela contra el balón para golpearlo. Cuanto más fuerte vueles contra él, más fuerte sale. Rosa defiende la portería oeste y ataca la este; menta es al revés. Tras un gol todos tienen unos segundos para volver para el saque.",
"j3lmwm": "Crear la partida",
"1clgctl": "¡Saque inicial!",
"mja9lm": "Persigue a los pilotos durante un minuto. Cerca, suave, la moto en el centro de la imagen, un whip o un gran salto, y las zonas de clipping: todo puntúa. Gana el mejor metraje.",
"1srrqzv": "Graba las batallas de drift durante un minuto. Cerca, suave, el coche en el centro de la imagen, los dos coches de una batalla, y las zonas de clipping: todo puntúa. Gana el mejor metraje.",
