"1iamjsl": "{0} tiene {1} {2} aquí, demasiado pocos para volar. En EdgeTX, pon el modo joystick USB en Classic y vuelve a enchufarla.",
"1m0xh9s": "Tu joystick",
"1iyz2p7": "No se encontró emisora ni mando. Conecta uno, ponlo en modo joystick y recarga.",
"awvaaq": "No se encontró emisora ni mando. Conecta uno, ponlo en modo joystick y muévelo.",
"1bcu86u": "{0}{1} está conectado, pero este navegador lo muestra con {2} {3}, y para volar hacen falta cuatro. En una emisora EdgeTX, pon el modo joystick USB del modelo en Classic, luego desenchufa la emisora y vuelve a enchufarla.",
"r0fr7u": "Un joystick",
"1k67jhh": "{0} no llega al simulador. Pausa para abrir la ayuda de sticks.",
"1g3lqvf": "Todavía no llega ninguna emisora ni mando a este navegador. Conéctalo, ponlo en modo joystick y mueve un stick: un navegador solo muestra un mando a una página cuando algo en él se mueve.",
"l55p9d": "Tu calibración guardada lee {0} de un eje que este mando no tiene, así que {1} nada. Tiene {2}. Calibrar sticks lo asigna de nuevo a partir de lo que envía de verdad.",
"10cte0": "El eje {0} se mueve como un stick, y nada en el simulador lo lee. El navegador tiene tu stick; el simulador lo tiene en el canal equivocado. Calibrar sticks lo arregla en un minuto más o menos.",
"13f86ul": "El eje {0} se mueve, y nada en el simulador lo lee. Si ese es el stick que no funciona, Calibrar sticks lo pone en el canal correcto.",
"3hxjne": "Eso es {0}, en el eje {1}, y está llegando al simulador.",
"4pid3q": "{0} se movió como un stick, y nada en el simulador lee {1}. Es un stick en el canal equivocado, y Calibrar sticks lo arregla.",
"13inlwb": "Mueve el stick que no funciona, hasta el final en cada extremo, y mira las barras.",
"2niqw0": "En la emisora: elige el modo joystick USB al enchufarla, antes de abrir esta página, y revisa el modelo seleccionado en ella. El modelo decide qué envía cada canal, y uno nuevo o vacío puede no enviar nada en un stick.",
"jem3gg": "Tu emisora llega como {0} ejes.",
"rr1z7d": "Si ninguna barra se mueve: Windows",
"1j91r00": "Comprueba si Windows ve el stick: pulsa Windows y R, escribe joy.cpl, pulsa Enter, elige tu emisora y abre Propiedades, luego muévelo. Si se mueve allí y aquí no, informa de un fallo desde esta pantalla y dilo.",
"1qj9g8y": "Si allí tampoco se mueve, la emisora no lo está enviando. Calibrar en esa ventana de Windows no cambia nada de lo que lee un navegador, así que no hace falta.",
"1elsn67": "Si ninguna barra se mueve: Mac",
"193sfmd": "macOS no tiene una prueba de sticks propia, así que estas barras son la prueba. Si un stick se mueve aquí en un navegador y no en otro, informa de un fallo desde esta pantalla y di cuál.",
"1lg87ci": "Si ninguna barra se mueve: Linux",
"fk484m": "jstest-gtk o evtest muestran lo que envía la emisora. Si el stick se mueve allí y aquí no, informa de un fallo desde esta pantalla y dilo.",
"1ftvq9i": "Si ninguna barra se mueve",
