"9s1w1d": "De una a cinco estrellas, una valoración por persona. Puedes cambiarla o retirarla. Los pilotos ven la media junto al nombre, y el tablero puede poner lo mejor primero.",
"fi2r1e": "Compartir este ajuste",
"d8h2dl": "Pone el ajuste con el que vuelas en el tablero público, con un código corto que cualquiera puede pegar para volarlo. Esto es lo que se sube, y solo esto:",
"86leg4": "No se incluye: tus gráficos, tus sticks y emisora, tu modo de vuelo y tus tiempos de vuelta. Cargar un ajuste nunca toca nada de eso.",
