"wkeoh8": "Cambiar (Y)",
"ypt803": "Ahora no (N)",
"4r9rjz": "Solo whoop: aterriza en el recuadro blanco",
"1dzhe8f": "Vuela por la puerta de salida",
"n816s8": "No hay plataformas de salida, así que el piloto empieza {0} m hacia dentro desde el borde izquierdo de la parcela, a media altura, mirando a la derecha.",
"1t711z2": "Haz clic en la parcela para colocarlo.",
"ekduh5": "Se apoya en lo que hay bajo el puntero: el suelo, un tejado, un contenedor.",
"8o0928": "La herramienta sigue en la mano, así que un segundo clic coloca otro.",
"1329ksr": "Haz clic en el suelo para poner el primer nodo de la carretera.",
"aaokh9": "Se curva por sus nodos como puede conducir un coche.",
"1cziowk": "Con la tecnología de",
"1kjx060": ". Escala de campo real, obstáculos reales, un plano que puedes entregar a un equipo.",
"ws88kv": "· Circuito {0}",
"ojeg79": "· Circuito {0}, Circuito {1}",
"1rqldy2": ". Traído a este simulador por andAgainFPV.",
"5k80a7": "Capítulo {0}: Primer vuelo, contrarreloj",
"1r5bgka": "Las carreras con teclado se vuelan en Angle. Los sticks son inclinación. Al soltar se nivela.",
"151jezz": "Una vuelta entera o más alrededor de un poste, volada panza arriba.",
"2h13ul": "CIRCUITOS DE CINCO PULGADAS",
"1ov5lw1": "circuitos de {0} pulgadas",
"tda83r": "CINCO PULGADAS",
"1sss0ee": "Capítulo {0}: Primer vuelo, a bordo",
"yajn08": "circuito de {0} pulgadas",
"1e05oqz": "Abre el editor en un campo vacío. Lo que hubiera en su lienzo se guarda en su lista Cargar. Los circuitos que construyes se quedan en este navegador. Borrarlo, o usar otro dispositivo, te hace empezar de cero. Publica un circuito para ponerlo en el tablero público.",
"1cdhqo": "Predeterminado de Betaflight",
"1dudsha": "por WebFPV",
"cuy5ed": "Cambia cualquier parte y estarás en un tablero distinto.",
"1iryycr": "El ajuste propio de Betaflight con un toque ligero: responde un poco antes a los sticks y rebota menos tras una parada. Abre Ajuste, donde se elige el ajuste y los deslizadores propios de Betaflight lo afinan. Tus rates se conservan.",
"k6akiz": "MAPAS DE FREESTYLE",
"10ufhmj": "{0} pulgadas",
"1r6qcm": "Leve",
"3sm2ze": "Fuerte",
"1xnvdto": "Un quad de freestyle y carreras de tamaño completo: ligero para su potencia, muy rápido, y un campo lo bastante grande para aprovecharlo. Cada aeronave guarda su propio ajuste, PID, batería, peso y cámara: cambiarla trae de vuelta los de esa máquina tal como los dejaste, o los de serie la primera vez, y cambia el editor entre un campo exterior y un salón. Tus propios rates van contigo, salvo que sigan siendo los de serie.",
"53x6f3": "Pega un código para compartir del tablero o de otro piloto. Primero ves lo que contiene, y puedes recuperar el tuyo.",
"9ww08a": "Multiplicador maestro",
"1vv9xkm": "Seguimiento, P e I",
"fetog5": "Deriva y bamboleo, I",
"kyk48v": "Amortiguación, D",
"1roremq": "Amortiguación dinámica, D max",
"1e0pboe": "Respuesta del stick, FF",
"we45r2": "Seguimiento de pitch",
"1dlny13": "Amortiguación de pitch",
"1b1bac5": "Todo lo de abajo pertenece a este, y cada ajuste guarda su propia afinación.",
"193v7i": "Todo a la vez: P, I, D y feedforward escalan juntos, manteniendo las proporciones. Este es el mando de \"hazlo más rígido\", y el que pedían los comentarios sobre la sensación de vuelo. De serie está en {0}; el preajuste rígido que antes venía aquí estaba en {1}, que es más o menos el tamaño del paso que pedían esos comentarios.",
"c3fbrt": "Con cuánta fuerza persigue el quad la velocidad que pide el stick. Bajo es perezoso y suave, alto se clava en la consigna y la mantiene.",
"amoq3u": "El término de error lento por sí solo. Demasiado bajo se desvía de la actitud en movimientos largos; demasiado alto se carga durante un movimiento largo de stick y lo suelta como un tirón cuando el stick se centra. En este modelo el tirón llega mucho antes que la deriva.",
"1kt9nne": "Resiste la rotación, suaviza las paradas, calma el propwash. En un quad real la D se paga con calor de motor y ruido de giroscopio; el giroscopio de este modelo está limpio, así que la amortiguación sale casi gratis y los ajustes rígidos la llevan alta.",
"1wqluz6": "Cuánta D extra llega durante movimientos y paradas rápidos, encima de la D base. Cero mantiene la D constante.",
"10nibr2": "El feedforward empuja con el propio movimiento del stick, antes de que exista ningún error. Alto es inmediato; demasiado alto se pasa al inicio de cada movimiento. Cero vuela solo con P y D.",
"i42c2o": "P e I de pitch respecto al roll. Un quad es más largo que ancho, así que el pitch suele llevar un pequeño porcentaje más.",
"1a9uio": "D de pitch respecto al roll, por la misma razón por la que existe el seguimiento de pitch.",
"1eviq1n": "Parte de: predeterminado de Betaflight",
"eq2omx": "Rates: Actual {0}/{1}/{2}",
"9nmf95": "Sensibilidad central",
"sdoqht": "Velocidad máxima",
"bns545": "Expo",
"v2q9fn": "Punto medio del acelerador",
"1xemf43": "Expo del acelerador",
"140ppwv": "{0} deg/s",
"1pq9vg": "{0}% de stick",
"bw3a2g": "Guarda los números de abajo con un nombre y vuelven con una pulsación, que es lo que pide un segundo circuito. Los preajustes se guardan solo en este navegador de este dispositivo. Borrar los datos del sitio, una ventana privada, otro navegador u otro dispositivo te hacen empezar de cero, y no hay cuenta ni se sube nada.",
"g0jyc7": "Lo rápido que responde el quad a un pequeño movimiento de stick, como la PENDIENTE de la curva en el centro.",
"idjhb0": "Bajo es tranquilo para una línea suave, alto es nervioso y rápido.",
"3gavi2": "No es la velocidad a medio stick: lee la curva.",
"1mlk7hb": "Configurator llama a esta columna Center Sensitivity.",
"1998vtg": "Lo que hace el quad con el stick a fondo, exactamente.",
"njxqki": "Este es el número para el que existen los rates Actual: el final de la curva es el número que escribes, haga lo que haga el expo con el centro.",
"1x3rl5q": "Cuánto del recorrido se gasta cerca del centro. Cero es una línea recta desde la sensibilidad central hasta el tope. Más alto suaviza el centro y mantiene el mismo máximo, por eso los extremos de la curva no se mueven cuando lo cambias.",
"7xrlm4": "Aplana el acelerador alrededor del punto medio y hace más empinados los extremos, exactamente el thr_expo de Betaflight. {0} es la línea recta de fábrica.",
"h1vu9t": "Ponles nombre a estos números y vuelven con una pulsación. Los preajustes se guardan solo en este navegador de este dispositivo. Borrar los datos del sitio, una ventana privada, otro navegador u otro dispositivo te hacen empezar de cero, y no hay cuenta ni se sube nada.",
"zsr042": "Modo {0}D",
"uqwbuw": "Modo {0}",
"1dcndpd": "Bajo",
"qv8t9n": "Apagado: vuelo normal, los motores giran en un sentido y la parte baja del acelerador es el ralentí. Para motores reversibles, como vuelan los pilotos de {0}D: el acelerador en el centro es cero empuje y por debajo vuelas invertido. Activarlo pregunta primero.",
"1u0xx": "Necesario para publicar un circuito o enviar un tiempo.",
"jky7ea": "{0} fps",
"sdsdu5": "Desde una pulsación de tecla hasta el fotograma que la mostró por primera vez, la mediana de tus últimas {0}, según lo informa este navegador; el retardo propio de la pantalla después de eso no está incluido. Un fotograma a {1} Hz son {2} ms. Aquí la GPU tarda unos {3} ms por fotograma, y los fotogramas hacen cola detrás de la página (la vista de baja latencia no está en uso).",
"fqq2qr": "Se mide desde tus propias pulsaciones y clics hasta el fotograma que los mostró por primera vez, así que se va llenando mientras usas los menús. Aquí la GPU tarda unos {0} ms por fotograma, y los fotogramas hacen cola detrás de la página (la vista de baja latencia no está en uso).",
"e3hxwq": "Puerta {0} de {1}",
