"1w35r80": "{0} km/h",
"1mb7nxr": "Los preajustes se guardan solo en este navegador de este dispositivo. Borrar los datos del sitio, una ventana privada, otro navegador u otro dispositivo te hacen empezar de cero, y no hay cuenta ni se sube nada.",
"11mwcph": "El ajuste propio de Betaflight con un toque ligero: responde un poco antes a los sticks y rebota menos tras una parada.",
"hdhajj": "Abre Ajuste, donde se elige el ajuste y los deslizadores propios de Betaflight lo afinan.",
