"1i1seu4": "O envíalo a {0} como su próxima ronda, listo para volar en el simulador.",
"1gvm7od": "¿Llevas una comunidad CommunityGow? Pega tu enlace de organizador para enviarle este circuito como próxima ronda.",
"hqk4t3": "Enlace de organizador",
"130csvk": "Enviar a esa comunidad",
"814v7v": "Esa es la página de la comunidad pero no el enlace de organizador: el enlace de organizador termina en #key= y algo después.",
"11v31i5": "Eso no es un enlace de organizador. Tiene este aspecto: https://webfpv.org/board/CommunityGow/your-club#key=...",
"13itu0x": "Ronda {0} para {1}.",
"lspki1": "Una ronda para {0}.",
"rrwq6r": "Las rondas de comunidad son circuitos de carreras de whoop. Abre uno desde Cargar, un circuito RaceGOW o uno tuyo, o empieza un circuito de whoop.",
"18q4smg": "Fija un orden de vuelo de al menos dos puertas y luego envíalo.",
"usn21g": "Carga un circuito RaceGOW o construye el tuyo. Cuando esté listo, envíalo: llega a la página de la comunidad, listo para volar en el simulador.",
"c9wfke": "Ahora no",
"5ri5sb": "Deja de crear una ronda en esta pestaña. La página de la comunidad puede abrirlo otra vez.",
"1ub9185": "Las rondas de comunidad son circuitos de carreras de whoop. Abre uno primero.",
"igjegc": "Una ronda necesita una vuelta: pon al menos dos elementos en el orden de vuelo.",
"13yf4ck": "{0} de {1} será este circuito. Esta pestaña dibuja primero su mapa, sus vistas y la animación de la vuelta, lo que lleva unos segundos, y luego el tablero lo pone en la página de la comunidad y en el simulador para todos los de allí.",
"m0vsxx": "La próxima ronda",
"z1j019": "Título de la ronda",
"1oa9hcs": "Enviar la ronda",
"1s50xl0": "Enviando {0} KB a {1}.",
