"1qmf27m": "La ronda {0} está publicada en {1}. El tablero no pudo poner su circuito en el simulador, así que la página no tiene botón Volar para ella.",
"idc2e9": "Todos los de la comunidad la ven en su página, donde una pulsación la vuela en el simulador. Comparte el enlace de la ronda en tu chat de grupo.",
