"3q1a5t": "{0} Su tarjeta en el tablero es una vuelta suya.",
"xs2wm3": "{0} Dibujando la imagen que muestra un enlace a él.",
"19mxe5g": "{0} Un enlace a él, publicado donde sea, muestra el {1}.",
"6m4wky": "Un circuito publicado necesita al menos una puerta en el orden de vuelo.",
"13d2z7y": "Esta es tu copia{0}{1}. Va al tablero como un circuito nuevo con el nombre de abajo. El original se queda.",
"14n7wyu": "El trazado cambió. Actualizar el tablero borrará los tiempos enviados. Un cambio de nombre solo los habría conservado.",
"2afyb6": "Este circuito ya está en el tablero. Actualizarlo conserva los tiempos si el trazado de vuelo no ha cambiado.",
"1juhhp2": "El tablero público guarda una copia de este circuito, con cada logo de patrocinador en las puertas, las banderas y la hierba. Los tiempos que envía la gente se guardan ahí.",
"zc26en": "Para qué sirve",
"1xcoxsd": "{0}. La gente filtra el tablero con estas.",
"1qouzhw": "Este navegador no tiene registro de las etiquetas que lleva este circuito en el tablero, así que no hay ninguna marcada. Déjalas así para conservar las que lleve, o marca algunas para reemplazarlas.",
"ruo7pi": "Opcional, y hasta {0}. La gente filtra el tablero con estas, así que un circuito sin ninguna es más difícil de encontrar.",
"1ssvw3n": "Ya son {0}. Desmarca una para añadir otra.",
"6zetyh": "Enviando el circuito, logos incluidos.",
"19diyk1": "Este id ya estaba en el tablero, así que subió como un circuito nuevo, \"{0}\".",
"18ndqbk": "El trazado de vuelo cambió, así que se borraron los tiempos antiguos.",
