"1sy6tsu": "Cerrar esta pestaña lo termina.",
"1m6q0hd": "Caduca a las {0}, y cerrar esta pestaña lo termina antes.",
"4xghzk": "Sesión iniciada en el tablero como {0}. {1} Publicar tiene un botón Marcar como oficial para cualquier circuito que esté en el tablero, y un circuito oficial se abre aquí para editarlo directamente, cosa que no hace para nadie más.",
