"29lt00": "Administrador del tablero",
"4j8gr8": "Para quienes llevan el tablero. Un administrador puede marcar un circuito como oficial. Después solo los administradores pueden abrirlo en el editor o cambiarlo, y todo el mundo puede seguir volándolo y enviando tiempos. Los demás siguen publicando y volando como siempre.",
