"89yb7x": "Hasta cinco logos de patrocinadores, pintados sobre {0} donde tú los pongas: pulsa \"Pintar sobre {1}\" debajo de uno y luego haz clic sobre {2}. Viajan dentro del archivo del mapa, así que un mapa que le envías a alguien llega con su marca puesta.",
"11oynza": "Hasta cinco logos de patrocinadores. Se reparten por las puertas en orden de vuelo, así que cada patrocinador recibe su parte de los paneles, las pancartas verticales y las banderas, repartida a lo largo de la vuelta en vez de amontonada en la salida. Cualquiera de ellos también se puede pintar sobre {0}: pulsa \"Pintar sobre {1}\" debajo de él y luego haz clic sobre {2}. Viajan dentro del archivo del circuito, así que un circuito que le envías a alguien llega con su marca puesta.",
