"duvt42": "El plano desde arriba, el lienzo que este editor ha tenido siempre. V para 3D",
"6hw2u8": "Construir aquí, en 3D: elige una pieza a la izquierda, haz clic sobre {0}, arrastra una pieza para moverla. V para 2D",
