"1qj2404": "Almacén",
"b82y15": "Tienda",
"dt4vyt": "Con red",
"1tc7k8s": "Pasarela",
"b4x696": "Kei car",
"8nyic1": "Furgoneta kei",
"1a9s81": "Compacto",
"muqpew": "Sedán",
"cudpbj": "Familiar",
"14553dv": "Monovolumen",
"1x05jcy": "Furgoneta",
"1s05rpl": "Camión de caja",
"15zbbz0": "Minibús",
"yvrloj": "Pino",
"it7z38": "Dorado",
"352p1v": "Mediodía",
"iz6qh4": "Atardecer",
"1ti6h5c": "Nublado",
"1kq6380": "Hora dorada: un sol bajo y cálido y sombras largas de color violeta. La luz propia de la ciudad.",
"r0wxsi": "Un sol alto y blanco, sombras cortas y duras y un cielo azul intenso.",
"ige15v": "El sol en el horizonte y un cielo violeta. Se encienden ventanas, farolas, vallas publicitarias y máquinas expendedoras.",
"1dpyzgh": "Un día plano, gris violeta, con sombras suaves y una bruma más cercana.",
"168a9r2": "Hormigón",
"dclqfz": "Asfalto",
"ogou1p": "Hierba",
"1cr7f7k": "Tierra",
"wnpobs": "Un patio de losas de hormigón cortadas, con una línea amarilla alrededor.",
"yi1f2h": "Un aparcamiento oscuro, con plazas y flechas pintadas alrededor de lo que coloques.",
"1a197nq": "Un césped dentro del bordillo. No tiene líneas pintadas salvo la caja de salida.",
"5uugym": "Un patio de tierra trabajada con roderas de neumáticos.",
"1rsee4x": "Barra superior",
"10fio7": "Barra inferior",
"1p2efal": "Poste izquierdo",
"rwyvy0": "Poste derecho",
"1qpcbmi": "Cerrar la paleta. Esc",
"3i96av": "Cerrar la paleta",
"youj61": "Extra",
"12q74ha": "Un logo de patrocinador pintado sobre {0}. Elige cuál de los logos lleva, y su tamaño, en el inspector.",
"15cdqf0": "Herramientas",
"1btcvp2": "Pulsa una tecla o haz clic en una herramienta, y luego haz clic sobre {0}. La herramienta sigue armada, así que diez puertas son diez clics. Escape o clic derecho la guarda.",
"13j46d9": "Pulsa una tecla o haz clic en una herramienta, y luego haz clic sobre {0}. Una puerta sigue armada, así que diez puertas son diez clics; un muro, una valla y una puerta ascendente van de una en una. Escape o clic derecho la guarda.",
"10m93q": "Carreteras y vehículos",
"1s59m59": "Puertas y marcadores",
"raiuna": "Pulsa una tecla o haz clic en una herramienta, y luego haz clic en la parcela. Una pieza se apoya en lo que haya bajo el puntero: el suelo, un tejado, un contenedor. La herramienta sigue armada. Los edificios, los contenedores y el set de skate se alinean con los puntos cardinales; todo lo demás gira libremente. Escape o clic derecho la guarda.",
"iq9t52": "Forma",
"l778r1": "Hacia dónde",
"12ph7be": "Los escalones van",
"ikr0w0": "Arriba",
"19o4rhx": "Abajo",
"12h9wk3": "La letra que pone el siguiente clic",
"yqr2c7": "Elemento",
"317ur": "Arrastra para moverlos juntos. Delete los quita. Selecciona uno para editar sus dimensiones.",
"1hc6e0r": "Un cubo es una sola pieza, cinco puertas que comparten su tubo. Se entra volando por una cara y se sale por otra: cambia cuáles con la herramienta Orden de vuelo.",
"19phq7s": "Base",
"duccyy": "Inclinación (grados)",
"1qy8eue": "Inclinación",
"1l115jq": "Inclinación 0 es una puerta vertical. Inclinación 90 tumba la abertura, así que se atraviesa recto hacia abajo o recto hacia arriba. Cualquier valor intermedio es una puerta de picado inclinada.",
"s3robe": "Diámetro",
"1tlglvi": "Entre puntas",
"yq4hld": "Convertir en letra",
"6vxj0r": "Esta puerta se convierte en una mayúscula de tubo, plantada donde está y mirando hacia donde mira, en el mismo puesto del orden de vuelo. El hueco por el que va la pasada es el que da tamaño a la letra.",
"10pf30j": "Ocupa el lugar de esta puerta en el circuito como letra",
"h8361q": "Texto",
"1ka8b9s": "En un mapa esto es mobiliario: nada se cronometra a través de él y no hay orden para volarlo. Es sólido, y está ahí para enhebrarlo.",
"9np4dk": "En el circuito, dos veces o más",
"1iqjs62": "En el circuito",
"1szogu2": "Decorado: construido y sólido, y no forma parte de la carrera.",
"7q7a5x": "No está en el orden de vuelo.",
"1bwo84t": "Añadir al circuito",
"1w1codh": "Volar otro hueco",
"10isy43": "Volar otro nivel",
"1e7iaf0": "Añade una pasada por el siguiente hueco de esta letra que aún no se vuela.",
"1dg08q4": "Añade otra puerta en esta torre, en la siguiente abertura sin usar.",
"ly0bei": "Tumbado",
"he0rjp": "De pie",
"16ql5dy": "Giro (grados)",
"19ab3xt": "Solo gira en cuartos de vuelta: está hecho de cajas, y quedan a escuadra con la sala.",
"1acjmu8": "Se alinea con los puntos cardinales, en cuartos de vuelta, hasta que la física aprenda cajas giradas.",
"nf3vcm": "Estilo",
"jw2n94": "Hundido {0} m en el suelo. Lo que queda bajo el suelo ni se dibuja ni es sólido; una Base negativa es la forma de esconder media pieza.",
"cbqqgg": "De pie es tan alto como largo, con la torre a su lado. El estilo abierto puesto de pie es un pozo cuadrado, abierto por ambos extremos: una línea para bajar en picado.",
"m2z3r": "De pie es tan alto como largo.",
