"17b4ml5": "Carretera abierta",
"qsrpfv": "Bucle",
"qzwunl": "Un bucle necesita tres nodos. Añade uno primero.",
"jj8vcf": "Unir el último nodo con el primero",
"1b9g4iv": "Un carril",
"1e0ga72": "Dos carriles",
"106c95b": "Inicio X",
"zwcngc": "Inicio Y",
"fi3pgh": "Todos los coches de una carretera abierta van por el centro, hasta el final y de vuelta.",
"s0eiot": "Un coche circula por la izquierda, a {0} m del centro, y uno puesto en Reversa va por el otro carril en sentido contrario.",
"6f5f8c": "Todos los coches van por el centro de su único carril, así que dos en sentidos opuestos se encontrarían de frente.",
"n6y7lw": "Esta carretera aún no tiene línea por la que circular: mira los avisos.",
