"14kd816": "Eliminar nodo",
"7fk9fq": "Atajo: Delete",
"psho8c": "Arrastra un nodo para cambiar la forma de la carretera, y arrastra la propia carretera para moverla. Arrastra un + entre dos nodos para añadir uno ahí. Haz clic en un nodo y pulsa Delete para quitarlo.",
"1535txm": "En esta carretera",
"19s6hea": "Aún no hay vehículos. Elige Vehículo en la paleta y haz clic en la carretera.",
"kwlyli": "Tráfico",
"e42w1e": "Coche de drift",
"1md37vj": "Toma las curvas el doble de fuerte y derrapa, con el morro metido en cada curva, a {0} km/h en las rectas",
"1rjqz7e": "Adelante",
"mqvh5x": "Reversa",
"1uu757d": "Velocidad e inicio",
"1p68bad": "Pintarlo de otro color",
"1gzljgt": "Adelante sale a lo largo de {0} desde su primer nodo, Reversa vuelve hacia él; en ambos casos da la vuelta en cada extremo.",
"orucb5": "Adelante va por el carril izquierdo en el orden en que se trazó la carretera, Reversa va por el otro carril en sentido contrario.",
"507afi": "Adelante da la vuelta en el orden en que se trazó la carretera, Reversa en sentido contrario.",
"qs5x7t": "Este vehículo no tiene carretera, así que se queda aparcado en la fila del borde sur de la parcela. Arrástralo a una carretera.",
"1rgtgzb": "Seleccionar su carretera",
"1kt144f": "Arrastra el coche para deslizarlo por su carretera. Un coche soltado en la mitad derecha de un bucle de dos carriles va por el otro carril.",
"1e9l9b2": "Nombre del hueco",
"1b5hejq": "Puntos",
"1s8mpdp": "Ventana",
"1xuswhn": "Una ventana de {0} m de ancho respecto a su rumbo y {1} m de alto desde su base, a {2} m del suelo. No es sólida ni se dibuja en el mundo: un piloto la encuentra al atravesarla.",
"1n1avl0": "Cómo se vuela",
"17kqvbs": "Cada hueco es una puerta propia. Elige la figura y luego vuela esa línea. La trazada muestra el rodeo.",
"101yslu": "Hacia dónde gira",
"z90btw": "Esta mezcla no es una figura con nombre. Cada hueco que listaste sigue contando como una puerta propia.",
"1epj4gy": "Trayectoria de vuelo",
"fdcfrv": "Qué trayectoria de vuelo",
"s3y93q": "Después",
"df9dnw": "Al entrar",
"1h51c6r": "Un giro alrededor de la bandera: se rodea y nunca se sobrevuela",
"1drm4l8": "Lo que hace la línea después de esta pasada",
