"lqv9ao": "La salida se inclina",
"10a5zjb": "Cerrado",
"xhs4he": "Nada puesto después de esta pasada: la línea sigue hasta la siguiente pieza.",
"v2b64n": "Nada puesto al entrar en esta pasada: la línea llega desde la pieza anterior.",
"jhv2pt": "También se llama {0}.",
"1ora819": "La línea pasa la bandera y sigue: sin giro alrededor.",
"140sy7r": "{0} Alrededor de la bandera con el margen de giro, así que se rodea y nunca se sobrevuela.",
"lrap3c": "Alrededor de esta puerta",
"puy9pc": "Alrededor de la bandera {0}",
"1skujz": "A través, y luego un 180 plano alrededor de la pata con bandera",
"1jqr4yn": "A través, y luego un 180 ascendente alrededor de la pata con bandera",
"1bazxbe": "A través, y luego un 180 descendente alrededor de la pata con bandera",
"uttsmo": "A través, un círculo completo alrededor de la pata con bandera, y otra vez por la puerta en el mismo sentido en que entró",
"1j8qdhd": "Ambas banderas",
"14tvr3z": "A través, alrededor de una pata, de vuelta a través, alrededor de la otra, de vuelta a través",
"1vx7m1b": "Media vuelta",
