"15dzcr6": "Pasa de largo por su lado de paso, sin giro alrededor",
"14n06mo": "Izquierda",
"hu52ng": "Gira a la izquierda a su alrededor, en sentido antihorario: queda a tu izquierda",
"8humpx": "Derecha",
"u4gd6q": "Gira a la derecha a su alrededor, en sentido horario: queda a tu derecha",
"aizr18": "Cuánto",
"18ol1p0": "Un cuarto de vuelta a su alrededor",
"1mroaab": "Media vuelta a su alrededor y de regreso por donde viniste",
"172qtq9": "Una vuelta completa a su alrededor",
