"1ljfjl3": "Bajando mientras da la vuelta",
"8grjfz": "Subiendo mientras da la vuelta",
"19f8jhg": "A una sola altura durante toda la vuelta",
"193mu7r": "Cómo lo rodea la línea",
"1d5l3kp": "Qué logo",
"fuh6y1": "{0}, encajado dentro de la huella de {1} por {2} m de arriba. Ajusta el tamaño de la huella a su forma y la llenará más.",
"u7r6mk": "Tamaño de la abertura",
"x8sjyl": "Estas puertas no son todas del mismo tamaño. Elige uno para ponérselo a todas.",
"1hzx9ty": "Un tamaño propio. Elige un preajuste para volver a uno estándar, o escribe la abertura abajo.",
"z7pdd0": "Separación entre niveles",
"120dj14": "{0} es la subida de una abertura a la siguiente, de borde inferior a borde inferior. Dos aberturas comparten un tubo del marco, así que la separación natural es el alto de la abertura más el tubo, que es lo que pone un preajuste.",
"vgll2t": "Una abertura redonda de {0}{1} de diámetro",
"15487wm": "Una abertura de seis lados de {0}{1} entre puntas y {2}{3} entre lados planos",
"1v2qxxn": "{0} aberturas, cada una de su tamaño. {1}.",
"6sk7cs": "{0} aberturas de {1} por {2}{3}. {4}.",
"1hbf8r7": "{0}, centro a {1}{2} sobre {3}.",
"zoltl8": "{0} Parte más alta de la estructura: {1}{2}.",
"1cy6t48": "Cada abertura",
"4ikah4": "Cada abertura de una torre es una puerta propia: dale su propio ancho y alto, y la carrera puntúa cada pasada según el tamaño propio de esa abertura. Una abertura que no toques tiene el tamaño de la torre, el de arriba.",
"sfqavh": "Ancho de la abertura {0}",
"lmcl0k": "Alto de la abertura {0}",
"1gbmevb": "Devolver la abertura {0} al tamaño de la torre",
"nfe36u": "Qué letra es esta",
"1m3kezv": "{0} Cada hueco es una puerta propia en el orden de vuelo: la pasada dice por cuál va.",
"1ugsv61": "Ancho de la letra",
"1s7eddk": "Alto de la letra",
"vq42m7": "{0}. El tubo es de 2 pulgadas, y el tubo de una letra es sólido.",
"18ku1py": "Convertir en puerta",
"h5sgwm": "Una puerta simple donde está el hueco principal, de su mismo tamaño. La pasada por cualquier otro hueco se quita del orden.",
"q7q9fq": "Marco",
"r64mng": "El tubo se ha quitado: los huecos siguen puntuando y encendiéndose, y no hay nada con lo que chocar. En la sala se ve solo como sus huecos.",
"s9vozj": "La letra está hecha de tubo. Hazla invisible para conservar sus huecos como objetivos sin nada construido alrededor.",
"1rkao2q": "Volver a poner el tubo",
"1ezapez": "Hacerla invisible",
"1h88uzq": "Cada lado es un tubo propio: la barra superior está sobre la abertura de arriba y la barra inferior bajo la más baja, y un poste es un tramo por abertura. Los botones Izquierda y Derecha quitan el poste entero; los botones de debajo quitan el tramo de una abertura. Quita uno y las aberturas siguen puntuando. En la vista 3D, haz clic en un tubo de la puerta seleccionada y pulsa Delete: eso quita solo el tramo en el que hiciste clic. Izquierda y derecha son vistas de frente a la puerta, como la bandera del travesaño.",
"3wzvo0": "Cada lado es un tubo propio. Quita uno y la abertura sigue puntuando y encendiéndose, sin tubo ahí con el que chocar. En la vista 3D, haz clic en un tubo de la puerta seleccionada y pulsa Delete. Izquierda y derecha son vistas de frente a la puerta, como la bandera del travesaño.",
"1vhm01f": "Quitar: {0}",
"80wioy": "Volver a poner: {0}",
"a9ak0k": "Quitar el tramo: {0}",
"1mtqtr1": "Volver a poner el tramo: {0}",
"1302s3v": "Volver a poner el marco",
"ka4wbv": "Volver a poner todos los lados",
"103wg51": "Quita todos los lados, y la bandera si la tiene: la abertura sigue puntuando y encendiéndose, sin nada con lo que chocar.",
"e2847m": "Bandera del travesaño",
"127gict": "Dónde van los banderines en una valla: en sus extremos. La altura del mástil es la altura de la bandera en las dimensiones de abajo, y el mástil es sólido.",
"17wx66j": "Dónde va el banderín en el travesaño superior, visto de frente a la puerta. Encima pone un mástil en el centro del panel, justo sobre la abertura. La altura del mástil es la altura de la bandera en las dimensiones de abajo, y el mástil es sólido: un piloto que baje en picado sobre la barra superior puede chocar con él.",
"d0y2y3": "Hueco",
"1w31kfz": "El cuadrado verde es el espacio por el que tienes que pasar volando. Arrastra el tirador redondo en el plano para moverlo a cualquier punto alrededor del marcador, toda la vuelta. Cambiar de lado lo manda al lado opuesto, y Recalcular lo devuelve a la regla automática, que es el exterior del giro.",
"1wg2ncb": "Invertir cara",
"172xku9": "Cambiar de lado",
"3d7qa3": "Atajo: X",
"1tdvisw": "Recalcular",
"qqpglk": "Devuelve esto a la regla automática, que lo orienta a lo largo de la línea que va del elemento anterior al siguiente.",
"1c086it": "Nada seleccionado. Haz clic en un elemento para editarlo, o arrastra un recuadro sobre suelo vacío para seleccionar varios.",
"3eggiu": ": RaceGOW, para un whoop de 65 mm en una sala. Puertas de 24 a 28 in, puertas contiguas a 30 in de centro a centro, y todo el circuito dentro de 4 por 6 ft con la puerta más pequeña, escalado con ellas. Cada pieza se mide en pulgadas desde el centro de la sala, y la cuadrícula es de una pulgada.",
"1329h41": ": un quad de cinco pulgadas en un campo. Tamaños de puerta de MultiGP, y cada pieza medida en metros desde la esquina del campo.",
"rkmjcd": "Ancho (m)",
"j1jla4": "Fondo (m)",
"d8gwxd": "Cuadrícula",
"1ldm6m9": "Hora de la carrera",
"kcgjh9": "Día",
"130fke9": "Noche",
"1vaao7c": "Una carrera nocturna: cielo oscuro, luna, y tira LED alrededor de cada puerta y a lo largo de cada bandera. Todo el que vuela este circuito lo vuela de noche.",
"1q1ve87": "Se vuela a la luz del día. Elige Noche para un cielo oscuro con tira LED alrededor de cada puerta.",
"nlsgyb": "Trazada",
"rjs65g": "Escala de tangentes",
"186guzs": "La longitud de las tangentes de la spline, como fracción de la distancia hasta el siguiente nudo. Alrededor de un tercio dibuja un arco circular en un ángulo recto. Más alto abomba la línea hacia fuera, más bajo cuadra las esquinas.",
"4qrm9v": "Avisar bajo radio",
"1ha03ei": "Muestras por segmento",
"x0kat6": "Mapa de freestyle",
"38aybj": ": un lugar para volar, sin circuito que lo atraviese. Construido con los propios recursos de la ciudad, volado con un cinco pulgadas, y cada sólido que colocas es sólido en el aire.",
"v92qmr": "Hora del día",
"1qwiu8u": "Suelo",
"3kq9uj": "Todo lo que colocas se ajusta a la cuadrícula; mantén Alt para colocar fuera de ella.",
"tl4rb": "Vacío. Al colocar una puerta o una torre se añade al orden. Una torre es una estructura y varias puertas: elige cómo se vuela en el inspector.",
"125vuu2": "Invertir la cara o el lado de paso. X",
"cvtpkr": "Quitarlo del orden",
"1rp3o0h": "No está en el circuito",
"17rv3f8": "Añadir",
"l5hiha": "Girarlo un cuarto. E lo gira hacia un lado y Q hacia el otro",
"18mc53g": "Una copia al lado, 30 in más allá. Control D",
"1yqq07p": "Todo lo demás: el marco, su tamaño, cómo se vuela una torre",
"fmuvol": "Todo lo demás: el marco, la bandera, cómo se vuela una torre",
"drzf67": "Soltarlo. Escape",
"52jpgy": "Soltarlo",
"zafenl": "Una sola pieza: puertas que comparten su tubo. Se entra volando por una cara y se sale por otra, y la herramienta Orden de vuelo cambia cuáles. Arrástrala para moverla. Q y E la giran. Las teclas de flecha la mueven un poco.",
"yuyk5l": "Arrastra uno para moverlos juntos. Q y E los giran. Las teclas de flecha los mueven un poco.",
"1czqdml": "Combínalas en una sola puerta: cruzar cualquiera de las aberturas cuenta, en el lugar de la primera que se vuela. Haz primero invisibles las dos para un objetivo en forma de L o de T sin nada construido.",
"206k6j": "Combinar en una puerta",
"pvyp1l": "Una puerta que puntúa el área de las dos. Separar lo deshace.",
"1s4mclz": "Tamaño de la puerta",
