"16bob4g": "Orden de vuelo: haz clic en la primera pieza por la que pasa la vuelta, y luego en la siguiente. Repetir una pieza es otra pasada.{0} Esc guarda la herramienta.",
"1h3i156": "Toca el suelo para poner un cubo: cinco puertas en una sola pieza, que se atraviesa recto hacia donde mira. La herramienta sigue armada. Toca Cubo otra vez para guardarla.",
"jihh0f": "Haz clic en el suelo para poner un cubo: cinco puertas en una sola pieza, que se atraviesa recto hacia donde mira. La herramienta sigue armada. Clic derecho o Esc la guarda.",
"1hjaiqs": "Guárdala desde Herramientas.",
"947ub9": "Tócala otra vez a la izquierda para guardarla.",
"ret7py": "Arrastra por el suelo para poner una fila de dos o tres puertas, a 30 in de distancia. Un clic pone un par. Clic derecho o Esc guarda la herramienta.",
"p956s2": "Haz clic en dos puntos para medir entre ellos. Un clic cerca de una puerta o de un palo toma su centro. Clic derecho o Esc guarda la regla.",
"6y6p5i": "Haz clic en dos puntos para medir entre ellos, en metros. Un clic cerca de una pieza toma su centro. Clic derecho o Esc guarda la regla.",
"na57ja": "Arrastra por el suelo, desde el vano que se vuela primero, para poner un muro. Un toque pone tres. Un muro, y la herramienta se guarda.",
"1x41sn8": "Arrastra por el suelo, desde el vano que se vuela primero, para poner un muro de puertas que comparten sus postes, de dos a seis. Un clic pone tres. Un muro, y la herramienta se guarda. Alt lo gira libremente.",
