"m8sun": "Haz clic",
"lzc7fh": "Las formas están en Herramientas.",
"ybq1cu": "{0} donde va la puerta de lanzamiento: una puerta horizontal a 15 ft de altura, que se atraviesa hacia arriba desde abajo, con el tirón y el empujón por encima que la vuelan puestos como puntos de paso. Una puerta, y la herramienta se guarda.",
"36gz3q": "{0} donde va la valla de barra: una barra de 10 ft de ancho y a 5 ft de altura sobre dos patas, atravesada en el circuito, con la vuelta pasando por encima. La tarjeta dice por debajo o rasante. Una valla, y la herramienta se guarda.",
"1onrj1y": "{0} donde va la valla: un panel de 4 m de largo y 1 m de alto con una bandera en cada extremo, atravesado en el circuito, con la vuelta pasando por encima. Una valla, y la herramienta se guarda.",
"1cwij39": "{0} donde va la puerta ascendente: inclinada 45 grados con su borde inferior a 1,5 m de altura, que se atraviesa hacia arriba. Una puerta, y la herramienta se guarda.",
"18zqy2o": "Haz clic sobre {0} para colocarlo. La herramienta sigue armada, así que un segundo clic coloca otro. Clic derecho o Esc la guarda.",
"gtzrzu": "Arrástralo para moverlo. Arrastra el anillo de su base para girarlo.",
"11yaxra": "Arrástralo para moverlo. Arrastra el anillo de su base para girarlo. Las teclas de flecha lo mueven un poco.",
"1k9grnp": "Herramientas tiene las piezas para colocar más.",
"1weh0ir": "Elige una herramienta a la izquierda para colocar más.",
"dmd4gm": "Haz clic en una puerta para seleccionarla. Arrastra sobre {0}, en una zona vacía, para mirar alrededor. Elige una herramienta a la izquierda para colocar más.",
"13ytpyk": "Clic derecho o Esc la guarda.",
"1sj82o4": "Clic derecho o Esc guarda la regla.",
"gy64hi": "Un coche circula por una carretera, y este mapa aún no tiene ninguna. Pon una antes con la herramienta Carretera.",
"1wq4lkk": "Haz clic en una pieza para seleccionarla. Arrástrala para moverla, y el anillo de su base la gira. Arrastra el suelo vacío para mirar alrededor. Elige una herramienta a la izquierda para colocar más.",
"1hid29q": "Abre Herramientas y elige {0}, y luego toca sobre {1}.",
"102rg1e": "O empieza desde un circuito RaceGOW terminado y mueve una puerta.",
"90n8s5": "Empezar desde un circuito RaceGOW",
