"14aviqa": "Empezar desde el patio",
"deqy8p": "Los mapas que vienen con el editor, y los que guardaste",
"vmluuy": "O empieza desde un circuito del tablero, y hazlo tuyo. Escuadra en la barra mantiene las puertas nuevas alineadas con los puntos cardinales, como se dibuja un plano.",
"4d31w9": "Los circuitos de cinco pulgadas de Mapas y Circuitos, cada uno abierto como tu propia copia",
