"7an3sj": "Para los coches y devuélvelos a donde empiezan",
"lf5j6j": "Conduce los coches por sus carreteras, como hará el simulador",
"td7316": "Aún no hay nada en el orden de vuelo. Coloca un elemento y se une al orden automáticamente.",
"scsh3n": "No hay plataformas de salida. La línea va del primer elemento al último y la vuelta no se cierra. Pulsa S para colocarlas.",
"91vn4y": "Sigue construido, y es sólido.",
"hmu6f5": "{0} tiene un tamaño demasiado pequeño para su tubo: al hueco por el que se vuela no le queda nada una vez que el tubo lo rodea, así que nada puede puntuar ahí. Haz la letra más grande.",
"1xhn5ud": "{0} tiene un hueco de solo {1} m en su parte más ancha, frente a los 1,5 m de una puerta estándar, así que un quad tiene poco sitio para volarlo. Si el circuito lo pide a propósito, ignora esto; si no, haz la letra más grande.",
"amkahr": "{0}. {1} no tiene cara de entrada definida, así que la línea eligió una.",
"1f6an1h": "{0} está fuera del campo.",
"up72l1": "{0} y {1} están en el mismo sitio, así que la línea no tiene dirección entre ambos.",
"1fgg8vv": "{0} le da la espalda a {1}. La línea sale al revés. Pulsa X para invertir la cara.",
"19psiq7": "{0} mira de vuelta hacia {1}. La línea llega al revés. Pulsa X para invertir la cara.",
"1xkwf83": "La vuelta sale alejándose de {0}. Gira las plataformas de salida, o reordena el circuito.",
"1vv4mnm": "La vuelta regresa a {0} por delante, después de {1}. Invierte esa cara, o mueve el último elemento detrás.",
"1gf0z7v": "Un quad a velocidad de carrera no vuela eso. Si el circuito lo pide a propósito, baja Avisar bajo radio en los ajustes del campo.",
"1bw4o5i": "Nada vuela eso.",
"rz1y7k": "La línea atraviesa {0} a los {1} m de la vuelta.",
"qlb5lu": "La línea sale del campo a los {0} m de la vuelta.",
"trp2du": "La línea pasa bajo el suelo a los {0} m de la vuelta.",
"63njfk": "{0} y {1} están a {2} m de distancia, uno tras otro en el orden de vuelo, así que una sola pasada puede alcanzar a ambos. La carrera solo cuenta {3} tras {4} m más de vuelo. Si la idea es una vuelta entre ambos, aleja uno.",
"1l1fncv": "{0} termina mirando en sentido contrario a {1}, así que la línea tiene que volver sobre sí misma para llegar ahí. Pon {2} donde termina la figura, o gira la figura hacia el otro lado.",
"1ozh84i": "{0} sale hacia atrás y entra en {1}, así que la línea tiene que volver sobre sí misma para empezar la figura. Gira {2} hacia el otro lado, o mueve la figura.",
"1emgxmg": "{0} empieza con rumbo de vuelta hacia {1}, así que la línea tiene que volver sobre sí misma para empezar la figura. Pon {2} donde empieza la figura, o gira la figura hacia el otro lado.",
"laqehz": "La línea pasa por encima de {0} a los {1} m de la vuelta. La línea de una bandera sube sin fin, así que se rodea y nunca se sobrevuela: mueve la línea a uno de sus lados.",
"1xr491b": "{0} está {1} grados fuera de escuadra respecto a {2}. Cada puerta mira a lo largo de uno de los dos ejes del circuito: gírala hasta un ángulo recto respecto al suyo.",
"1tgybl6": "{0} tiene una abertura de {1}. Una puerta RaceGOW cabe en un cuadrado de 28 in.",
"1rlgckd": "{0} tiene una abertura de {1}. La puerta mínima de RaceGOW es de 24 in.",
"6we35z": "{0} tiene el centro de su abertura inferior a {1}. Una puerta en el suelo tiene su centro a 20 in o menos.",
"1d69zcl": "La segunda abertura de {0} está centrada a {1}. La puerta de arriba de una torre de dos debe estar al menos a 42 in de altura.",
"xv7gqv": "La tercera abertura de {0} está centrada a {1}. Una tercera puerta debe estar al menos a 69 in de altura.",
"1imcxyb": "{0} llega a {1} y atraviesa el techo de {2} m. Los circuitos RaceGOW se vuelan en interior.",
"19w4clv": "{0} apila sus aberturas a {1} de distancia. Las puertas contiguas van de 27 a 33 in de centro a centro, apiladas o lado a lado.",
"1ims1cr": "{0} y {1} están a {2} de distancia. Dos puertas tan cercanas son contiguas, y las puertas contiguas van de 27 a 33 in de centro a centro.",
"8wy7kh": "{0} y {1} están a {2} de distancia. Si la idea es un par lado a lado, las puertas contiguas van de 27 a 33 in de centro a centro, nominalmente 30.",
"107lerp": "{0} está a {1} de {2}. Un palo va al menos a 14 in del centro de una puerta.",
"1uyg16": "{0} y {1} están a {2} de distancia. Dos palos van al menos a 36 in uno de otro.",
"zolwjx": "El circuito ocupa {0} por {1} m. Un circuito RaceGOW cabe en {2} por {3} m con este tamaño de puerta.",
"4hr5zo": "Pulsa S y haz clic donde deben empezar.",
"lk5z4a": "La fila además queda sobre dos alturas: la plataforma {0} está a {1} m y la de la aeronave a {2} m, así que las plataformas se dibujan a {3} m y algunas flotan o quedan enterradas. Mueve la fila a una sola superficie.",
"ls6ln3": "Las plataformas de salida quedan sobre dos alturas: la plataforma {0} está a {1} m y la de la aeronave a {2} m. Las plataformas se dibujan a {3} m, así que algunas flotan o quedan enterradas. Mueve la fila a una sola superficie.",
"1hy0328": "{0} choca con {1}: una cosa está construida a través de la otra. Mueve una de las dos.",
"500wke": "{0} y {1} dejan entre ambos una ranura de {2} m. Un cinco pulgadas necesita {3} m para pasar, así que ciérrala o ábrela más.",
"10fprle": "Las aspas de {0} girarían a través de {1}. Mueve una de las dos cosas, o gira el molino.",
"h9gzex": "{0} no se vuela: un mapa vuela una sola caza de globos, {1}. Quita una de las dos.",
"ym814r": "{0} tiene {1} atravesando su ventana, así que nada la cruza limpio. Mueve el hueco o lo que tiene dentro.",
"1l0co51": "Un hueco con nombre",
"d008ky": "{0} está fuera de la parcela.",
"g0m2mr": "{0} sobresale del borde de la parcela.",
"np34nj": "{0} queda por completo bajo el suelo, así que nada se ve y nada es sólido. Sube su Base para que salga.",
"2cz3wz": "Este mapa tiene {0} sólidos, por encima de los {1} que un mapa no debe superar para cargar y volar con fluidez en una máquina lenta. El mayor es {2}, con {3}.",
"1o9p6b3": "Alrededor de {0} la física tendría {1} formas que comprobar contra una aeronave, y comprueba {2} como máximo: el resto se queda fuera, y una aeronave ahí podría atravesarlas. Separa más estos elementos o usa menos.",
"36jvfa": "{0} no tiene carretera: {1}. Se queda aparcado, y se dibuja en la fila del borde sur de la parcela. Arrástralo a una carretera, o bórralo.",
"58628i": "{0} se sale del borde de la parcela.",
"kof9h3": "{0} atraviesa {1}: un coche que circule por ella chocaría. Mueve la carretera, o {2}, hasta que un coche tenga sitio para pasar.",
"1x8yhyt": "{0} pasa sobre las plataformas de salida, así que un coche que circule por ella atraviesa la aeronave que espera para despegar. Mueve la carretera o las plataformas.",
"11r26o9": "{0} pasa a menos de un metro de donde sale la aeronave, así que un coche que circule por ella roza la aeronave antes de que deje la plataforma. Mueve la carretera o las plataformas.",
"e5birv": "{0} pasa por donde empieza el piloto cuando no hay plataformas de salida, así que un coche que circule por ella atraviesa la aeronave. Mueve la carretera, o pulsa S y pon las plataformas de salida lejos de ella.",
"5s8foe": "{0} y {1} están los dos en {2}, una carretera abierta: todos los coches van por el centro hasta el final y de vuelta, así que los dos se encuentran de frente y se atraviesan. Cierra la carretera en bucle, o deja un solo coche en ella.",
"1c7ews2": "{0} y {1} van por el único carril de {2} en sentidos opuestos, así que se encuentran de frente y se atraviesan. Dale dos carriles a la carretera, o dale la vuelta a uno de los dos.",
"b92v0l": "Dales la misma velocidad máxima y el mismo drift, o pon uno en Reversa para que vaya por el otro carril.",
"1t8095q": "Dales la misma velocidad máxima y el mismo drift, o dale dos carriles a la carretera y pon uno en Reversa.",
"ntbmqa": "{0} empieza encima de {1}. Desliza uno de los dos por la carretera.",
